      default: return 'bg-white/10 text-white border-white/10';
    }
  };

  return (
    <motion.div
      whileHover={{ y: -5 }}
      className="glass p-8 rounded-3xl flex flex-col h-full group hover:border-white/20 transition-all cursor-pointer"
      onClick={() => onOpen(project)}
