            <motion.div
              initial={{ opacity: 0, scale: 0.95, y: 10 }}
              animate={{ opacity: 1, scale: 1, y: 0 }}
              exit={{ opacity: 0, scale: 0.95, y: 10 }}
              className="absolute bottom-[-20px] z-50 glass px-6 py-4 rounded-2xl border border-[#F5F5DC]/20 max-w-xs text-center shadow-2xl"
            >
              <span className="text-[9px] font-black uppercase tracking-widest text-[#F5F5DC] block mb-2">
                {hoveredNode.subLabel}
              </span>
              <p className="text-slate-200 text-xs leading-relaxed font-medium">
                "{hoveredNode.description}"
              </p>
            </motion.div>
          )}
        </AnimatePresence>
      </div>
    </section>
  );
};

export default ProjectWeb;

import React, { useState, useEffect } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { ExternalLink, Github, X, ChevronRight, User, AlertCircle, ArrowUpRight, Lock, Sparkles, ShieldCheck, ShieldAlert } from 'lucide-react';
import { PROJECTS } from '../constants';
import { Project, ProjectStatus } from '../types';
import SEO from './SEO';

const ProjectCard: React.FC<{ project: Project; onOpen: (p: Project) => void }> = ({ project, onOpen }) => {
  const getStatusColor = (status: ProjectStatus) => {
    switch (status) {
      case ProjectStatus.LIVE: return 'bg-emerald-500/10 text-emerald-400 border-emerald-500/20';
      case ProjectStatus.PROTOTYPE: return 'bg-[#F5F5DC]/10 text-[#F5F5DC] border-[#F5F5DC]/20';
      case ProjectStatus.IN_PROGRESS: return 'bg-slate-500/10 text-slate-400 border-slate-500/20';
      default: return 'bg-white/5 text-white border-white/10';
    }
  };

  return (
    <motion.div
      whileHover={{ y: -5 }}
      className="glass p-6 sm:p-8 rounded-[2rem] flex flex-col h-full group hover:border-[#F5F5DC]/20 transition-all cursor-pointer relative"
      onClick={() => onOpen(project)}
    >
      <div className="flex justify-between items-start mb-6">
        <span className={`px-2.5 py-1 rounded-full text-[8px] font-black uppercase tracking-wider border ${getStatusColor(project.status)}`}>
          {project.status}
        </span>
        <div className="text-slate-500 group-hover:text-[#F5F5DC] transition-colors">
          <ChevronRight size={16} />
        </div>
      </div>

      <h3 className="text-xl font-bold mb-3 group-hover:text-[#F5F5DC] transition-colors line-clamp-1">{project.title}</h3>
      <p className="text-slate-400 text-xs leading-relaxed mb-6 flex-grow line-clamp-3">{project.description}</p>

      <div className="flex flex-wrap gap-2 mb-8">
        {project.tags.slice(0, 3).map(tag => (
          <span key={tag} className="px-2 py-0.5 rounded-md bg-white/5 text-[8px] text-slate-500 uppercase font-black tracking-tighter border border-white/5">
            {tag}
          </span>
        ))}
      </div>

      <div className="pt-5 border-t border-white/5 flex items-center justify-between mt-auto">
        <div className="text-[10px] text-slate-500 font-bold flex items-center gap-1.5 uppercase tracking-tight">
          <User size={12} className="text-[#F5F5DC]/60" />
          {project.role}
        </div>

        {project.id === 'wealth-sprint' && (
          <div className="flex items-center gap-1.5 px-3 py-1.5 rounded-xl bg-[#F5F5DC]/5 text-[#F5F5DC] text-[9px] font-black uppercase tracking-tighter border border-[#F5F5DC]/10">
            <ShieldCheck size={12} /> Confidential Data
          </div>
        )}
      </div>
    </motion.div>
  );
};

const ProjectModal: React.FC<{ project: Project; onClose: () => void }> = ({ project, onClose }) => {
  return (
    <>
      <SEO title={`${project.title} Project`} description={project.seoDescription || project.description} />
      <motion.div 
        initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }}
        className="fixed inset-0 z-[60] flex items-center justify-center p-4 sm:p-6 bg-slate-950/90 backdrop-blur-xl"
        onClick={onClose}
      >
        <motion.div 
          initial={{ y: 20, opacity: 0 }} animate={{ y: 0, opacity: 1 }} exit={{ y: 20, opacity: 0 }}
          className="glass w-full max-w-sm rounded-[2.5rem] relative flex flex-col max-h-[90vh] overflow-hidden"
          onClick={e => e.stopPropagation()}
        >
          <button onClick={onClose} className="absolute top-6 right-6 p-2 rounded-full glass border-white/10 text-slate-400 hover:text-white transition-all z-50"><X size={16} /></button>

          <div className="overflow-y-auto modal-content p-8 pt-12 custom-scrollbar">
            <span className="text-[8px] font-black text-[#F5F5DC] uppercase tracking-[0.2em] mb-2 block">{project.status}</span>
            <h3 className="text-2xl font-bold mb-6 pr-8">{project.title}</h3>

            <div className="space-y-6">
              <div className="p-5 rounded-2xl bg-[#F5F5DC]/5 border border-[#F5F5DC]/10">
                <h4 className="text-[9px] font-black text-slate-500 uppercase tracking-widest mb-1">Impact</h4>
                <p className="text-slate-200 text-xs sm:text-sm leading-relaxed font-medium">{project.outcome}</p>
              </div>

              <div>
                <h4 className="text-[9px] font-black text-slate-500 uppercase tracking-widest mb-2">Technical Summary</h4>
                <p className="text-slate-400 text-xs sm:text-sm leading-relaxed">{project.description}</p>
              </div>

              {project.subLinks && project.subLinks.length > 0 && (
                <div className="space-y-2">
                  <h4 className="text-[9px] font-black text-slate-500 uppercase tracking-widest mb-3">Resources</h4>
                  {project.subLinks.map((sub, i) => {
                    const isConfidential = sub.name === "Confidential Data";
                    return (
                      <a 
                        key={i} href={sub.url} target="_blank" rel="noopener noreferrer"
                        className={`flex items-center justify-between p-4 rounded-2xl border transition-all group/sub ${isConfidential ? 'bg-[#F5F5DC]/10 border-[#F5F5DC]/20 hover:border-[#F5F5DC]/40' : 'bg-white/5 border-white/5 hover:bg-white/10'}`}
                      >
                        <div className="flex flex-col">
                          <span className={`text-xs font-bold ${isConfidential ? 'text-[#F5F5DC]' : 'text-slate-200'}`}>{sub.name}</span>
                          {isConfidential && <span className="text-[8px] font-medium text-[#F5F5DC]/60 uppercase tracking-tighter">Only for Collaborators</span>}
                        </div>
                        {isConfidential ? <Lock size={14} className="text-[#F5F5DC]" /> : <ArrowUpRight size={14} className="text-slate-500" />}
                      </a>
                    );
                  })}
                </div>
              )}

              <div className="flex flex-wrap gap-1.5 pt-4">
                {project.tags.map(tag => (
                  <span key={tag} className="px-2 py-0.5 rounded-lg bg-white/5 border border-white/10 text-[8px] text-slate-500 uppercase font-black">{tag}</span>
                ))}
              </div>
            </div>
          </div>

          <div className="p-8 border-t border-white/5 bg-white/[0.02]">
            {project.isPrivate ? (
              <div className="flex items-center justify-center gap-2 px-6 py-4 rounded-2xl bg-slate-900/50 text-slate-500 font-bold text-xs border border-white/5 opacity-50 cursor-not-allowed">
                Private Deployment <Lock size={14} />
              </div>
            ) : project.link ? (
              <a href={project.link} target="_blank" rel="noopener noreferrer" className="flex items-center justify-center gap-2 px-6 py-4 rounded-2xl bg-[#F5F5DC] text-black font-black text-xs hover:bg-white transition-all shadow-xl shadow-[#F5F5DC]/10">
                Launch Application <ExternalLink size={14} />
              </a>
            ) : (
              <span className="flex items-center justify-center py-4 rounded-2xl bg-white/5 text-slate-500 font-bold text-xs border border-white/10 italic">Module under construction</span>
            )}
          </div>
        </motion.div>
      </motion.div>
    </>
  );
};

const Projects: React.FC = () => {
  const [selectedProject, setSelectedProject] = useState<Project | null>(null);

  useEffect(() => {
    if (selectedProject) document.body.classList.add('modal-open');
    else document.body.classList.remove('modal-open');
    return () => document.body.classList.remove('modal-open');
  }, [selectedProject]);

  return (
    <section id="projects" className="py-20 border-t border-white/5">
      <div className="flex flex-col md:flex-row md:items-end justify-between gap-4 mb-16 px-4 sm:px-0">
        <div>
          <h2 className="text-3xl font-bold mb-4">Functional Projects</h2>
          <p className="text-slate-500 max-w-xl text-sm font-medium">Every module is a step toward autonomous financial logic.</p>
        </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 gap-8 px-4 sm:px-0">
        {PROJECTS.map((project) => (
          <ProjectCard key={project.id} project={project} onOpen={setSelectedProject} />
        ))}
      </div>

      <AnimatePresence>
        {selectedProject && <ProjectModal project={selectedProject} onClose={() => setSelectedProject(null)} />}
      </AnimatePresence>
    </section>
  );
};

export default Projects;
